 void Update(){runtimeViewport=new Vector2(Screen.width,Screen.height);if(!safe)return;var area=simulateSafeArea?simulatedSafeArea:Screen.safeArea;if(area!=lastSafe||lastScreen!=new Vector2(Screen.width,Screen.height)){ApplySafeArea(area,new Vector2(Screen.width,Screen.height));ApplySettings();}if(scanning){float p=Mathf.Clamp01((Time.unscaledTime-scanBegin)/.8f);scanProgress.rectTransform.anchorMax=new Vector2(.05f+.9f*p,.2f);scanProgressText.text="SCANNING • local simulated sensor "+Mathf.RoundToInt(p*100)+"%";if(p>=1)CompleteScan();}if(Time.unscaledTime>=nextRefresh){nextRefresh=Time.unscaledTime+1/Mathf.Clamp(refreshHz,1,10);Refresh();}foreach(var pair in resources){var fill=pair.Value.Item2.rectTransform;var a=fill.anchorMax;float target=targetFill[pair.Key];if(a.x!=target){a.x=Mathf.Abs(a.x-target)<.0005f?target:Mathf.Lerp(a.x,target,1-Mathf.Exp(-12*Time.unscaledDeltaTime));fill.anchorMax=a;}}}
 public void ApplySafeArea(Rect area,Vector2 size){lastSafe=area;lastScreen=size;if(!safe)return;safe.anchorMin=new Vector2(area.xMin/size.x,area.yMin/size.y);safe.anchorMax=new Vector2(area.xMax/size.x,area.yMax/size.y);safe.offsetMin=safe.offsetMax=Vector2.zero;}
 public ResearchTarget CurrentTarget(){if(!game||game.prototype.driving)return null;ResearchTarget nearest=null;float d=3;foreach(var t in environment.targets)if(t){float v=Vector3.Distance(game.prototype.ActivePosition(),t.transform.position);if(v<=d){d=v;nearest=t;}}return nearest;}
 public void Refresh(){if(!game||!game.initialized)return;foreach(var id in resources.Keys){var snapshot=telemetry.Read(id);var pair=resources[id];pair.Item1.text=snapshot.available?$"{snapshot.current:F1} / {snapshot.max:F0}\n{snapshot.current/snapshot.max*100:F1}% • {snapshot.status}":"NOT CONNECTED";pair.Item1.color=!snapshot.available?theme.secondary:snapshot.current<=15?theme.critical:snapshot.current<=30?theme.orange:theme.text;pair.Item2.color=snapshot.current<=15?theme.critical:snapshot.current<=30?theme.orange:id=="oxygen"?theme.oxygen:theme.orange;targetFill[id]=snapshot.Fraction;}
 if(cachedScans!=game.scans.Count){if(cachedScans>=0&&game.scans.Count>cachedScans)syncStatus="Pending Export • local only";cachedScans=game.scans.Count;}if(settingsSummary)settingsSummary.text="Quality: "+new[]{"Low","Medium","High","Desktop"}[Mathf.Clamp(settings.quality,0,3)]+"  |  HUD: "+new[]{"Full","Compact","Minimal","Hidden"}[settings.visibility];branding.text="ASTROGATEWAY\n"+game.registry.displayName+"\nLOCAL TRAINING • PROVISIONAL";weatherReadout.text=game.prototype.WeatherName+"\nTemperature / wind: not connected\nSol clock: not implemented\nSession "+TimeSpan.FromSeconds(game.prototype.elapsed).ToString(@"mm\:ss");objectiveScans=environment.targets.Count(t=>t&&game.scans.Any(s=>Vector3.Distance(s.location,t.transform.position)<=3));objectivesReadout.text=objectivesCollapsed?"Objectives collapsed":game.prototype.objective+"\n\nResearch stations "+objectiveScans+" / "+environment.targets.Length+"\nScans: "+game.scans.Count+" (simulated)\nORBIS upload: unavailable";
 roverReadout.text=game.registry.rover+"  |  "+game.modes.Mode.ToString().ToUpperInvariant()+$"\nBAT {game.battery:F1}%     {Mathf.Abs(game.prototype.driving?game.prototype.speed:0):F1} m/s\nCONDITION {game.health:F1}% • SIMULATED";
 recentReadout.text=game.scans.Count==0?"RECENT SCAN\nNo scientific samples recorded":ScanText(game.scans[game.scans.Count-1]);syncLabel.text=syncStatus;bool driving=game.prototype.driving;runControl.GetComponentInChildren<Text>().text=driving?"ACCELERATE":"RUN";brakeControl.SetActive(driving&&settings.visibility<3);var target=CurrentTarget();scanButton.interactable=InputAllowed&&target;scanButton.GetComponentInChildren<Text>().text=scanning?"SCANNING":"SCAN";bool nearRover=Vector3.Distance(game.prototype.ActivePosition(),game.prototype.rover.transform.position)<=5;bool nearDoor=environment.closedAirlocks.Any(x=>x&&Vector3.Distance(game.prototype.ActivePosition(),x.position)<4);interactButton.interactable=InputAllowed&&(driving||nearRover||target||nearDoor);interactButton.GetComponentInChildren<Text>().text=driving?"EXIT ROVER":nearRover?"BOARD ROVER":target?"INSPECT":nearDoor?"AIRLOCK":"INTERACT";contextLabel.text=target?"TARGET • "+target.displayName:driving?"Stop before exiting":nearRover?game.registry.rover:"No interaction in range";if(!string.IsNullOrEmpty(lastResult))contextLabel.text+="\n"+lastResult;float alpha=environment.sun&&environment.sun.intensity>1.4f?Mathf.Max(settings.opacity,.8f):settings.opacity;foreach(var panel in panels)if(panel)panel.color=new Color(theme.panel.r,theme.panel.g,theme.panel.b,alpha);UpdateMap();dirty=false;}
 string ScanText(ScientificScan s)=>"RECENT SCAN • SIMULATED\n"+s.type+" | tick "+s.tick+"\nSynthetic index "+s.syntheticIndex.ToString("F3")+" (dimensionless)\nNo chemical measurement available";
 void MapPlace(RectTransform icon,Vector3 world,bool global=false){var center=global?Vector3.zero:game.prototype.ActivePosition();var pos=new Vector2(world.x-center.x,world.z-center.z)/250*(global?1:settings.mapZoom);pos=global?new Vector2(Mathf.Clamp(pos.x,-.49f,.49f),Mathf.Clamp(pos.y,-.49f,.49f)):Vector2.ClampMagnitude(pos,.46f);icon.anchorMin=icon.anchorMax=new Vector2(.5f,.5f)+pos;icon.anchoredPosition=Vector2.zero;}
 void UpdateMap(){mapBackground.localScale=Vector3.one*settings.mapZoom;var center=game.prototype.ActivePosition();mapBackground.anchoredPosition=new Vector2(-center.x,-center.z)/250*settings.mapZoom*mapDisk.rect.width;foreach(var pair in mapIcons)if(pair.Item1)MapPlace(pair.Item2,pair.Item1.position);MapPlace(playerMarker,game.prototype.ActivePosition());playerMarker.localRotation=Quaternion.Euler(0,0,-(game.prototype.driving?game.prototype.rover.transform.eulerAngles.y:game.prototype.astronaut.transform.eulerAngles.y));playerMarker.GetComponent<Image>().sprite=theme.heading?theme.heading:theme.circle;playerMarker.sizeDelta=new Vector2(13,18);waypointMarker.gameObject.SetActive(hasWaypoint);if(hasWaypoint)MapPlace(waypointMarker,waypoint);}
 public void BeginScan(){if(!InputAllowed||scanning)return;scanTarget=CurrentTarget();if(!scanTarget){lastResult="No valid target in range";return;}scanning=true;scanBegin=Time.unscaledTime;game.modes.Switch(ControlMode.Menu);ClearInput();scanCancel.SetActive(true);dirty=true;}
 public void CompleteScan(){if(!scanning)return;bool valid=scanTarget&&Vector3.Distance(game.prototype.ActivePosition(),scanTarget.transform.position)<=3&&!environment.paused;if(valid&&game.modes.Mode==ControlMode.Menu)game.modes.Switch(ControlMode.Astronaut);bool success=valid&&scanTarget.TryScan(game);if(!valid&&!environment.paused&&game.modes.Mode==ControlMode.Menu)game.modes.Switch(ControlMode.Astronaut);scanning=false;scanCancel.SetActive(false);lastResult=success?"Simulated scan recorded":"Scan cancelled or rejected";if(success){environment.AssociateScans();syncStatus="Pending Export • local only";}Refresh();}
 public void CancelScan(){bool active=scanning;scanning=false;if(active&&!environment.paused&&game.modes.Mode==ControlMode.Menu)game.modes.Switch(ControlMode.Astronaut);if(scanCancel)scanCancel.SetActive(false);lastResult="Scan cancelled";ClearInput();}
 public void Interact(){if(!InputAllowed)return;if(game.prototype.driving||Vector3.Distance(game.prototype.ActivePosition(),game.prototype.rover.transform.position)<=5){lastResult=game.Interact()?"Control mode updated":"Action blocked: stop rover / clear exit";}else if(CurrentTarget())OpenDetail("Scientific equipment",CurrentTarget().displayName+"\nLocal simulated sensor; use SCAN to record.");else OpenDetail("ARESYN airlock","Sealed. Habitat interiors are not implemented.");Refresh();}
 public bool SaveLocal(){bool ok=game.Save();syncStatus=ok?"Saved Locally":"Failed • local save";dirty=true;return ok;}
 public bool LoadLocal(){bool ok=game.Load();syncStatus=ok?"Loaded Locally":"Failed • local load";cachedScans=game.scans.Count;Refresh();return ok;}
 public bool ExportLocal(){try{game.Export(Path.Combine(Application.persistentDataPath,"CinematicHUD_Exports"));syncStatus="Exported Locally";dirty=true;return true;}catch{syncStatus="Failed • local export";dirty=true;return false;}}
 public void ClearInput(){movement=lookDelta=Vector2.zero;runHeld=brakeHeld=false;foreach(var p in GetComponentsInChildren<HUDPointerControl>(true))p.Clear();if(game&&game.modes)game.modes.Submit(default);}
 public void TogglePause(){if(modalOpen){CloseModal();return;}if(!environment.paused){OpenDetail("Simulation paused","Local provisional training. No remote sync.\nSave and export use the existing native data model.");}else environment.SetPaused(false);}
 RectTransform OpenModal(string title){CancelScan();ClearInput();wasPaused=environment.paused;environment.SetPaused(true);modalOpen=true;if(modal)Destroy(modal);var shade=Image("Modal input shield",safe,Vector2.zero,Vector2.one,null,new Color(0,0,0,.62f),true);modal=shade.gameObject;var card=Image("Modal card",shade.transform,new Vector2(.27f,.16f),new Vector2(.73f,.86f),theme.rounded,new Color(.075f,.09f,.11f,.98f),true).rectTransform;Text("Modal title",card,title,new Vector2(.06f,.87f),new Vector2(.85f,.97f),27);Button("Close modal",card,"CLOSE / ESC",new Vector2(.68f,.015f),new Vector2(.96f,.085f),CloseModal);return card;}
 public void CloseModal(){if(modal){texts.RemoveAll(t=>t.Item1&&t.Item1.transform.IsChildOf(modal.transform));Destroy(modal);}modal=null;modalOpen=false;if(!wasPaused)environment.SetPaused(false);ClearInput();dirty=true;}
 public void OpenDetail(string title,string text){var card=OpenModal(title);var viewport=Rect("Scrollable report",card,new Vector2(.06f,.31f),new Vector2(.94f,.83f));viewport.gameObject.AddComponent<RectMask2D>();var scroll=viewport.gameObject.AddComponent<ScrollRect>();var body=Text("Details",viewport,text,new Vector2(0,1),new Vector2(1,1),22);body.rectTransform.pivot=new Vector2(.5f,1);body.gameObject.AddComponent<ContentSizeFitter>().verticalFit=ContentSizeFitter.FitMode.PreferredSize;scroll.viewport=viewport;scroll.content=body.rectTransform;scroll.horizontal=false;scroll.scrollSensitivity=28;Button("Save snapshot",card,"SAVE LOCAL",new Vector2(.05f,.16f),new Vector2(.33f,.25f),()=>{SaveLocal();CloseModal();});Button("Load snapshot",card,"LOAD LOCAL",new Vector2(.36f,.16f),new Vector2(.64f,.25f),()=>{LoadLocal();CloseModal();});Button("Export files",card,"EXPORT LOCAL",new Vector2(.67f,.16f),new Vector2(.95f,.25f),()=>{ExportLocal();CloseModal();});}
 public void OpenInventory(){OpenDetail("Inventory",game.inventory.Count==0?"Inventory empty.\nItem collection is not implemented.":string.Join("\n",game.inventory));}
 public void OpenSamples(){OpenDetail("Scientific sample records",game.scans.Count==0?"No samples. Approach a research station and scan.":string.Join("\n\n",game.scans.TakeLast(3).Select(ScanText))+"\nLatest 3 shown; export contains all records.");}
 public void OpenMap(){var card=OpenModal("ARESYN • world map");var board=Image("Expanded map",card,new Vector2(.06f,.18f),new Vector2(.94f,.82f),theme.map,new Color(.65f,.59f,.48f));var aspect=board.gameObject.AddComponent<AspectRatioFitter>();aspect.aspectMode=AspectRatioFitter.AspectMode.WidthControlsHeight;aspect.aspectRatio=1;foreach(var pair in mapIcons){var icon=Image(pair.Item1.name,board.transform,Vector2.one*.5f,Vector2.one*.5f,theme.circle,Accent);icon.rectTransform.sizeDelta=Vector2.one*10;MapPlace(icon.rectTransform,pair.Item1.position,true);}var player=Image("Current player",board.transform,Vector2.one*.5f,Vector2.one*.5f,theme.circle,theme.oxygen);player.rectTransform.sizeDelta=Vector2.one*14;MapPlace(player.rectTransform,game.prototype.ActivePosition(),true);Text("Map note",card,"NORTH ↑ • 250m playable square • markers from world coordinates\nExpanded map is a paused snapshot",new Vector2(.05f,.09f),new Vector2(.95f,.17f),16,TextAnchor.MiddleCenter);}
 void Slider(string name,RectTransform parent,float y,float min,float max,float value,Action<float> change){var label=Text(name,parent,name+" "+value.ToString("F2"),new Vector2(.06f,y),new Vector2(.43f,y+.055f),18);var track=Image(name+" track",parent,new Vector2(.46f,y),new Vector2(.91f,y+.06f),theme.rounded,new Color(.25f,.3f,.34f),true);var slider=track.gameObject.AddComponent<UnityEngine.UI.Slider>();slider.minValue=min;slider.maxValue=max;slider.value=value;var fill=Image("Fill",track.transform,Vector2.zero,Vector2.one,theme.rounded,Accent);slider.fillRect=fill.rectTransform;var handle=Image("Handle",track.transform,Vector2.zero,new Vector2(0,1),theme.circle,theme.text);handle.rectTransform.sizeDelta=new Vector2(32,32);slider.handleRect=handle.rectTransform;slider.targetGraphic=handle;slider.onValueChanged.AddListener(v=>{change(v);label.text=name+" "+v.ToString("F2");ApplySettings();PersistSettings();});}
 public void OpenSettings(){var card=OpenModal("HUD & GRAPHICS SETTINGS");settingsSummary=Text("Current settings",card,"",new Vector2(.06f,.82f),new Vector2(.94f,.865f),16);Slider("Panel opacity",card,.76f,.55f,.85f,settings.opacity,v=>settings.opacity=v);Slider("UI scale",card,.68f,.85f,1.15f,settings.uiScale,v=>settings.uiScale=v);Slider("Text scale",card,.60f,.85f,1.25f,settings.textScale,v=>settings.textScale=v);Slider("Joystick size",card,.52f,.8f,1.3f,settings.joystickSize,v=>settings.joystickSize=v);Slider("Control sensitivity",card,.44f,.3f,2f,settings.sensitivity,v=>settings.sensitivity=v);Slider("Map zoom",card,.36f,1,2,settings.mapZoom,v=>settings.mapZoom=v);Button("Visibility profile",card,"HUD PROFILE",new Vector2(.06f,.24f),new Vector2(.33f,.32f),CycleVisibility);Button("Graphics preset",card,"GRAPHICS",new Vector2(.36f,.24f),new Vector2(.63f,.32f),()=>{settings.quality=(settings.quality+1)%4;environment.ApplyQuality(settings.quality);PersistSettings();});Button("Handedness",card,"JOYSTICK SIDE",new Vector2(.66f,.24f),new Vector2(.94f,.32f),()=>{settings.leftHanded=!settings.leftHanded;ApplySettings();PersistSettings();});Button("Floating joystick",card,"FIXED / FLOATING",new Vector2(.06f,.12f),new Vector2(.49f,.20f),()=>{settings.floatingJoystick=!settings.floatingJoystick;ApplySettings();PersistSettings();});Button("Weather cycle",card,"WEATHER PREVIEW",new Vector2(.52f,.12f),new Vector2(.94f,.20f),()=>{game.prototype.SetWeather((game.prototype.weather+1)%3);dirty=true;});}
 public void CycleVisibility(){settings.visibility=(settings.visibility+1)%4;ApplySettings();PersistSettings();}
 public void ApplySettings(){settings.opacity=Mathf.Clamp(settings.opacity,.55f,.85f);settings.uiScale=Mathf.Clamp(settings.uiScale,.85f,1.15f);settings.textScale=Mathf.Clamp(settings.textScale,.85f,1.25f);settings.joystickSize=Mathf.Clamp(settings.joystickSize,.8f,1.3f);settings.sensitivity=Mathf.Clamp(settings.sensitivity,.3f,2);settings.visibility=Mathf.Clamp(settings.visibility,0,3);if(!safe)return;scaler.referenceResolution=new Vector2(1920,1080)/settings.uiScale;foreach(var panel in panels)if(panel)panel.color=new Color(theme.panel.r,theme.panel.g,theme.panel.b,settings.opacity);foreach(var t in texts)if(t.Item1)t.Item1.fontSize=Mathf.Max(Mathf.RoundToInt(t.Item2*settings.textScale),Mathf.CeilToInt(12/Mathf.Max(.1f,uiRoot.GetComponent<Canvas>().scaleFactor)));foreach(var go in fullOnly)go.SetActive(settings.visibility==0);foreach(var go in compactOnly)go.SetActive(settings.visibility<=1);foreach(Transform child in safe)if(child.gameObject!=modal&&child.gameObject!=restoreButton&&child.name!="Independent camera gesture zone"&&settings.visibility==3)child.gameObject.SetActive(false);if(settings.visibility<3){foreach(Transform child in safe)if(child.gameObject!=modal&&child.gameObject!=restoreButton&&!fullOnly.Contains(child.gameObject)&&!compactOnly.Contains(child.gameObject)&&child.gameObject!=scanCancel)child.gameObject.SetActive(true);}restoreButton.SetActive(settings.visibility>=2);joystick.localScale=Vector3.one*settings.joystickSize;joystick.anchorMin=new Vector2(settings.leftHanded?.60f:.025f,.12f);joystick.anchorMax=new Vector2(settings.leftHanded?.745f:.17f,.37f);var pointer=joystick.GetComponent<HUDPointerControl>();pointer.floating=settings.floatingJoystick;brakeControl.SetActive(game.prototype.driving&&settings.visibility<3);ClearInput();dirty=true;}
 public void PersistSettings(){PlayerPrefs.SetString(SettingsKey,JsonUtility.ToJson(settings));PlayerPrefs.Save();}
 public void LoadSettings(){try{settings=JsonUtility.FromJson<HUDSettings>(PlayerPrefs.GetString(SettingsKey,JsonUtility.ToJson(settings)))??new HUDSettings();}catch{settings=new HUDSettings();}}
 void OnApplicationFocus(bool f){if(!f)ClearInput();}void OnApplicationPause(bool p){if(p)ClearInput();}
 void OnDestroy(){if(telemetry)telemetry.Changed-=MarkDirty;if(game&&game.modes)game.modes.Changed-=OnMode;if(Application.platform==RuntimePlatform.Android)Screen.orientation=priorOrientation;}
}}
